<template>
  <section class="presentation-panel">
    <header class="presentation-header">
      <div><strong>{{ t('presentationStudio') }}</strong><p>{{ t('presentationStudioHint') }}</p></div>
      <nav><button v-for="tab in tabs" :key="tab.id" :class="{ active: activeTab === tab.id }" @click="activeTab = tab.id">{{ t(tab.label) }}</button></nav>
    </header>

    <div v-if="activeTab === 'ui'" class="studio-grid">
      <section class="studio-card">
        <header><strong>{{ t('responsiveUi') }}</strong><span>{{ selectedUi?.name ?? t('noUiSelection') }}</span></header>
        <p>{{ t('responsiveUiHint') }}</p>
        <div class="button-row"><button class="primary" @click="createCanvas">+ {{ t('createCanvas') }}</button><button :disabled="!selectedUi" @click="saveUiScene">{{ t('saveUiScene') }}</button></div>
        <dl><div><dt>{{ t('layoutContainers') }}</dt><dd>{{ layoutCounts }}</dd></div><div><dt>{{ t('focusableControls') }}</dt><dd>{{ focusableCount }}</dd></div><div><dt>{{ t('reusableUiScenes') }}</dt><dd>{{ uiPrefabCount }}</dd></div></dl>
      </section>
      <section class="studio-card responsive-preview-card">
        <header><strong>{{ t('responsivePreview') }}</strong><span>{{ previewPreset.label }}</span></header>
        <div class="responsive-tools"><select v-model.number="previewPresetIndex"><option v-for="(preset,index) in previewPresets" :key="preset.label" :value="index">{{ preset.label }}</option></select><label><span>DPI</span><input v-model.number="previewDpi" type="number" min="0.5" max="4" step="0.25"></label><label><span>{{ t('safeArea') }}</span><input v-model="previewSafeArea" type="checkbox"></label><label><span>RTL</span><input v-model="previewRtl" type="checkbox"></label></div>
        <div class="device-preview" :class="{ rtl: previewRtl }" :style="devicePreviewStyle"><i v-if="previewSafeArea"></i><div><strong>{{ t('gameTitle') }}</strong><button disabled tabindex="-1">{{ t('play') }}</button><button disabled tabindex="-1">{{ t('settings') }}</button></div></div>
        <button :disabled="!selectedCanvas" @click="applyPreviewToCanvas">{{ t('applyToCanvas') }}</button>
      </section>
      <section class="studio-card theme-editor">
        <header><strong>{{ t('uiThemes') }}</strong><button @click="newTheme">+ {{ t('newTheme') }}</button></header>
        <label><span>{{ t('uiTheme') }}</span><select v-model="selectedThemeReference"><option value="">{{ t('none') }}</option><option v-for="asset in themeAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
        <template v-if="themeDraft">
          <label><span>{{ t('name') }}</span><input v-model="themeDraft.name" maxlength="120"></label>
          <label><span>{{ t('parentTheme') }}</span><select v-model="themeDraft.parentTheme"><option :value="null">{{ t('none') }}</option><option v-for="asset in themeAssets.filter(item => assetReference(item.uuid) !== selectedThemeReference)" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label>
          <label><span>{{ t('accentColor') }}</span><input v-model="themeAccent" type="color"></label>
          <label><span>{{ t('surfaceColor') }}</span><input v-model="themeSurface" type="color"></label>
          <label><span>{{ t('cornerRadius') }}</span><input v-model.number="themeRadius" type="number" min="0" max="100"></label>
          <label><span>{{ t('spacingToken') }}</span><input v-model.number="themeSpacing" type="number" min="0" max="100"></label>
          <label><span>{{ t('typographyToken') }}</span><input v-model.number="themeFontSize" type="number" min="6" max="160"></label>
          <label><span>{{ t('variants') }}</span><input :value="Object.keys(themeDraft.variants).join(', ')" readonly></label>
          <div class="theme-preview"><button disabled>{{ t('normal') }}</button><button class="hovered" disabled>{{ t('hovered') }}</button><input readonly :placeholder="t('placeholder')"></div>
          <button class="primary" @click="saveTheme">{{ t('saveTheme') }}</button>
        </template>
      </section>
      <section class="studio-card ui-audio-card"><header><strong>{{ t('uiAudioReferences') }}</strong><span>{{ t('audioMixerSeparateHint') }}</span></header><label v-for="slot in uiAudioSlots" :key="slot"><span>{{ t(slot) }}</span><select v-model="uiAudioSettings[slot]" @change="commitPresentation"><option :value="null">{{ t('none') }}</option><option v-for="asset in audioAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.name }}</option></select></label><label><span>{{ t('audioBus') }}</span><select v-model="uiAudioSettings.bus" @change="commitPresentation"><option v-for="bus in audioSettings.mixer.buses" :key="bus.id">{{ bus.id }}</option></select></label></section>
    </div>

    <div v-else-if="activeTab === 'localization'" class="localization-workspace">
      <aside class="locale-settings studio-card">
        <header><strong>{{ t('localization') }}</strong><span class="create-locale"><input v-model="newLocale" placeholder="en-US" maxlength="35"><button :disabled="!newLocale.trim()" @click="createLocale">+ {{ t('locale') }}</button></span></header>
        <label><span>{{ t('sourceLocale') }}</span><input v-model="localizationSettings.sourceLocale" @change="commitPresentation"></label>
        <label><span>{{ t('liveLocalePreview') }}</span><select v-model="localizationSettings.previewLocale" @change="commitPresentation"><option v-for="locale in knownLocales" :key="locale">{{ locale }}</option></select></label>
        <label><span>{{ t('pseudolocalization') }}</span><input v-model="localizationSettings.pseudolocalization" type="checkbox" @change="commitPresentation"></label>
        <label><span>{{ t('pseudolocalizationMode') }}</span><select v-model="localizationSettings.pseudolocalizationMode" @change="commitPresentation"><option value="accented">Accented</option><option value="expanded">Expanded</option><option value="bidi">BiDi</option></select></label>
        <label><span>{{ t('expansionRatio') }}</span><input v-model.number="localizationSettings.expansionRatio" type="number" min="0" max="2" step="0.05" @change="commitPresentation"></label>
        <label><span>{{ t('fallbackChain') }}</span><input :value="localizationSettings.fallbackChain.join(', ')" @change="setFallbacks"></label>
        <strong class="minor-heading">{{ t('buildLocales') }}</strong>
        <label v-for="locale in knownLocales" :key="locale" class="check"><input :checked="localizationSettings.buildLocales.includes(locale)" type="checkbox" @change="toggleBuildLocale(locale, $event)"><span>{{ locale }}</span></label>
      </aside>
      <section class="table-editor studio-card">
        <header><select v-model="selectedLocaleReference"><option value="">{{ t('chooseLocalizationTable') }}</option><option v-for="asset in localeAssets" :key="asset.uuid" :value="assetReference(asset.uuid)">{{ asset.settings.localizationSettings.locale }} · {{ asset.name }}</option></select><button :disabled="!localeDraft" @click="addLocaleEntry">+ {{ t('entry') }}</button><button :disabled="!localeDraft" @click="exportCsv">CSV ↓</button><button :disabled="!localeDraft" @click="csvImport?.click()">CSV ↑</button><button class="primary" :disabled="!localeDraft" @click="saveLocale">{{ t('saveTable') }}</button><input ref="csvImport" hidden type="file" accept=".csv,text/csv" @change="importCsv"></header>
        <div v-if="localeDraft" class="locale-meta"><label><span>{{ t('locale') }}</span><input v-model="localeDraft.locale"></label><label><span>{{ t('textDirection') }}</span><select v-model="localeDraft.direction"><option value="ltr">LTR</option><option value="rtl">RTL</option></select></label><label><span>{{ t('fallbackLocale') }}</span><input v-model="localeDraft.fallbackLocale"></label><label><span>{{ t('displayName') }}</span><input v-model="localeDraft.metadata.displayName"></label><label><span>{{ t('nativeName') }}</span><input v-model="localeDraft.metadata.nativeName"></label><label><span>{{ t('fontFallbacks') }}</span><input :value="localeDraft.fontFallbacks.join(', ')" @change="setFontFallbacks"></label></div>
        <div v-if="localeDraft" class="locale-rows"><article v-for="(value,key) in localeDraft.entries" :key="key"><code :title="localeDraft.contexts[key]">{{ key }}</code><input v-model="localeDraft.contexts[key]" :placeholder="t('context')"><textarea :value="displayLocaleValue(value)" @change="setLocaleValue(key, $event)"></textarea><button @click="removeLocaleEntry(key)">×</button></article></div>
        <footer v-if="localeDraft" class="localization-report"><strong>{{ t('localizationReport') }}</strong><span>{{ extractedKeys.length }} {{ t('keys') }} · {{ missingEntries.length }} {{ t('missing') }}</span><code v-for="item in missingEntries.slice(0,12)" :key="`${item.locale}:${item.key}`">{{ item.locale }} · {{ item.key }} · {{ item.source }}</code></footer>
        <p v-else class="empty-state">{{ t('noLocalizationTable') }}</p>
      </section>
    </div>

    <div v-else-if="activeTab === 'audio'" class="audio-workspace">
      <section class="mixer studio-card">
        <header><strong>{{ t('audioMixer') }}</strong><button @click="addBus">+ {{ t('audioBus') }}</button></header>
        <div class="master-controls"><label><span>{{ t('masterVoiceLimit') }}</span><input v-model.number="audioSettings.mixer.masterVoiceLimit" type="number" min="1" max="1024" @change="commitAudio"></label><button @click="captureSnapshot">+ {{ t('snapshot') }}</button><select v-model="audioSettings.mixer.activeSnapshot" @change="commitAudio"><option :value="null">{{ t('liveMix') }}</option><option v-for="snapshot in audioSettings.mixer.snapshots" :key="snapshot.id" :value="snapshot.id">{{ snapshot.name }}</option></select></div>
        <div class="bus-list"><article v-for="bus in audioSettings.mixer.buses" :key="bus.id">
          <header><strong>{{ bus.name }}</strong><meter min="0" max="1" :value="audioDiagnostics.busMeters[bus.id] ?? 0"></meter><button :class="{ active: bus.mute }" @click="bus.mute = !bus.mute; commitAudio()">M</button><button :class="{ active: bus.solo }" @click="bus.solo = !bus.solo; commitAudio()">S</button><button v-if="bus.id !== 'Master' && !defaultBuses.includes(bus.id)" @click="removeBus(bus.id)">×</button></header>
          <label><span>{{ t('volume') }}</span><input v-model.number="bus.gain" type="range" min="0" max="1" step="0.01" @change="commitAudio"><output>{{ Math.round(bus.gain * 100) }}%</output></label>
          <label><span>{{ t('voiceLimit') }}</span><input v-model.number="bus.voiceLimit" type="number" min="1" max="512" @change="commitAudio"></label>
          <details><summary>{{ t('effects') }} ({{ bus.effects.length }})</summary><div v-for="effect in bus.effects" :key="effect.id" class="effect-row"><select v-model="effect.kind" @change="commitAudio"><option>LowPass</option><option>HighPass</option><option>Compressor</option><option>Delay</option><option>Reverb</option></select><input v-model="effect.enabled" type="checkbox"><input v-model.number="effect.wet" type="range" min="0" max="1" step="0.01"><button @click="bus.effects.splice(bus.effects.indexOf(effect),1); commitAudio()">×</button></div><button :disabled="bus.effects.length >= 8" @click="addEffect(bus)">+ {{ t('effect') }}</button></details>
          <details><summary>{{ t('sends') }} ({{ bus.sends.length }})</summary><div v-for="send in bus.sends" :key="`${send.target}-${bus.sends.indexOf(send)}`" class="effect-row"><select v-model="send.target" @change="commitAudio"><option v-for="target in audioSettings.mixer.buses.filter(item => item.id !== bus.id)" :key="target.id" :value="target.id">{{ target.name }}</option></select><input v-model="send.enabled" type="checkbox"><input v-model.number="send.gain" type="range" min="0" max="1" step="0.01"><button @click="bus.sends.splice(bus.sends.indexOf(send),1); commitAudio()">×</button></div><button :disabled="bus.sends.length >= 16" @click="addSend(bus)">+ {{ t('send') }}</button></details>
        </article></div>
      </section>
      <aside class="audio-inspector studio-card">
        <header><strong>{{ t('waveformPreview') }}</strong><select v-model="selectedAudioGuid"><option value="">{{ t('chooseAudioAsset') }}</option><option v-for="asset in audioAssets" :key="asset.uuid" :value="asset.uuid">{{ asset.name }}</option></select></header>
        <svg class="waveform" viewBox="0 0 512 100" preserveAspectRatio="none" aria-hidden="true"><polyline :points="waveformPoints" /><line v-if="selectedAudio" :x1="loopMarker(selectedAudio.settings.audioSettings.loopStart)" y1="0" :x2="loopMarker(selectedAudio.settings.audioSettings.loopStart)" y2="100" /><line v-if="selectedAudio && selectedAudio.settings.audioSettings.loopEnd > 0" class="loop-end" :x1="loopMarker(selectedAudio.settings.audioSettings.loopEnd)" y1="0" :x2="loopMarker(selectedAudio.settings.audioSettings.loopEnd)" y2="100" /></svg>
        <template v-if="selectedAudio"><label><span>{{ t('normalizeAudio') }}</span><input v-model="selectedAudio.settings.audioSettings.normalize" type="checkbox" @change="commitAssetAudio"></label><label><span>{{ t('targetPeak') }}</span><input v-model.number="selectedAudio.settings.audioSettings.targetPeakDb" type="number" min="-24" max="0" step="0.1" @change="analyzeWaveform"></label><label><span>{{ t('streamAudio') }}</span><input v-model="selectedAudio.settings.audioSettings.streaming" type="checkbox" @change="commitAssetAudio"></label><label><span>{{ t('loopMarkers') }}</span><div><input v-model.number="selectedAudio.settings.audioSettings.loopStart" type="number" min="0" :max="selectedAudio.duration" step="0.01" @change="commitAssetAudio"><input v-model.number="selectedAudio.settings.audioSettings.loopEnd" type="number" min="0" :max="selectedAudio.duration" step="0.01" @change="commitAssetAudio"></div></label></template>
        <dl class="voice-report"><div><dt>{{ t('activeVoices') }}</dt><dd>{{ audioDiagnostics.activeVoices }}</dd></div><div><dt>{{ t('streamingVoices') }}</dt><dd>{{ audioDiagnostics.streamingVoices }}</dd></div><div><dt>{{ t('bufferedVoices') }}</dt><dd>{{ audioDiagnostics.bufferedVoices }}</dd></div><div><dt>{{ t('limitedVoices') }}</dt><dd>{{ audioDiagnostics.limitedVoices }}</dd></div><div><dt>{{ t('virtualVoices') }}</dt><dd>{{ audioDiagnostics.virtualVoices }}</dd></div><div><dt>{{ t('audioLatency') }}</dt><dd>{{ audioDiagnostics.baseLatencyMs === null ? 'n/a' : `${audioDiagnostics.baseLatencyMs.toFixed(1)} ms` }}</dd></div><div><dt>{{ t('audioUnderruns') }}</dt><dd>{{ audioDiagnostics.underruns }}</dd></div><div><dt>{{ t('audioDeviceChanges') }}</dt><dd>{{ audioDiagnostics.deviceChanges }}</dd></div></dl>
        <button @click="addDucking">+ {{ t('duckingRule') }}</button><article v-for="rule in audioSettings.mixer.ducking" :key="rule.id" class="duck-rule"><select v-model="rule.triggerBus" @change="commitAudio"><option v-for="bus in audioSettings.mixer.buses" :key="bus.id" :value="bus.id">{{ bus.name }}</option></select><span>→</span><select v-model="rule.targetBus" @change="commitAudio"><option v-for="bus in audioSettings.mixer.buses" :key="bus.id" :value="bus.id">{{ bus.name }}</option></select><input v-model.number="rule.reductionDb" type="number" min="-80" max="0" @change="commitAudio"></article>
      </aside>
    </div>

    <div v-else class="accessibility-grid">
      <section class="studio-card"><header><strong>{{ t('runtimeAccessibility') }}</strong><span>{{ t('separateEditorSettings') }}</span></header><label><span>{{ t('keyboardNavigation') }}</span><input v-model="runtimeAccessibilitySettings.keyboardNavigation" type="checkbox" @change="commitPresentation"></label><label><span>{{ t('gamepadNavigation') }}</span><input v-model="runtimeAccessibilitySettings.gamepadNavigation" type="checkbox" @change="commitPresentation"></label><label><span>{{ t('screenReaderMetadata') }}</span><input v-model="runtimeAccessibilitySettings.screenReaderMetadata" type="checkbox" @change="commitPresentation"></label><label><span>{{ t('announceFocus') }}</span><input v-model="runtimeAccessibilitySettings.announceFocusChanges" type="checkbox" @change="commitPresentation"></label><label><span>{{ t('focusRingColor') }}</span><input v-model="runtimeAccessibilitySettings.focusRingColor" type="color" @change="commitPresentation"></label><label><span>{{ t('focusRingWidth') }}</span><input v-model.number="runtimeAccessibilitySettings.focusRingWidth" type="number" min="1" max="12" @change="commitPresentation"></label><label><span>{{ t('runtimeReduceMotion') }}</span><input v-model="runtimeAccessibilitySettings.reducedMotion" type="checkbox" @change="commitPresentation"></label><label><span>{{ t('highContrast') }}</span><input v-model="runtimeAccessibilitySettings.highContrast" type="checkbox" @change="commitPresentation"></label><label><span>{{ t('textScale') }}</span><input v-model.number="runtimeAccessibilitySettings.textScale" type="number" min="0.75" max="3" step="0.05" @change="commitPresentation"></label><label><span>{{ t('minimumTargetSize') }}</span><input v-model.number="runtimeAccessibilitySettings.minimumTargetSize" type="number" min="24" max="128" @change="commitPresentation"></label></section>
      <section class="studio-card audit-card"><header><strong>{{ t('accessibilityAudit') }}</strong><span>{{ accessibilityIssues.length }}</span></header><dl><div><dt>{{ t('focusableControls') }}</dt><dd>{{ focusableCount }}</dd></div><div><dt>{{ t('labeledControls') }}</dt><dd>{{ labeledControlCount }} / {{ focusableCount }}</dd></div><div><dt>{{ t('inputRemapWidgets') }}</dt><dd>{{ remapWidgetCount }}</dd></div></dl><article v-for="issue in accessibilityIssues" :key="`${issue.source}:${issue.code}`" :class="issue.severity"><strong>{{ issue.code }}</strong><span>{{ issue.entityName }} · {{ issue.message }}</span><code>{{ issue.source }}</code></article><p v-if="!accessibilityIssues.length">{{ t('accessibilityAuditPassed') }}</p></section>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { assetReference, assetState, moveAsset, readTextAsset, resolveAsset } from '../assets/AssetDatabase'
import { t } from '../i18n'
import { physicsState, pushHistory } from '../store/physics'
import { createPrefabFromEntities } from '../runtime/prefabs'
import { createLocalizationTable, exportLocalizationCsv, extractLocalizationKeys, importLocalizationCsv, localizationSettings, missingLocalizationReport, readLocalizationTable, writeLocalizationTable, type LocalizationTable, type LocalizationValue } from '../runtime/localization'
import { createUiTheme, readUiTheme, writeUiTheme, type UiThemeDocument } from '../runtime/uiTheme'
import { runtimeAccessibilitySettings, uiAudioSettings } from '../runtime/presentation'
import { audioRuntime, normalizeAudioSettings, type AudioMixerBusSettings } from '../runtime/audio'
import { requestConfirmation } from '../store/dialog'
import { createUiEntity } from '../store/physics'
import { auditUiAccessibility } from '../runtime/uiAccessibility'
import type { Canvas, Checkbox, Panel, RectTransform, Text } from '../world/components'

type Tab = 'ui' | 'localization' | 'audio' | 'accessibility'
const props = withDefaults(defineProps<{ initialTab?: Tab }>(), { initialTab: 'ui' })
const tabs = [{ id: 'ui' as const, label: 'responsiveUi' }, { id: 'localization' as const, label: 'localization' }, { id: 'accessibility' as const, label: 'accessibility' }]
const activeTab = ref<Tab>(props.initialTab), selectedThemeReference = ref(''), themeDraft = ref<UiThemeDocument | null>(null), selectedLocaleReference = ref(''), localeDraft = ref<LocalizationTable | null>(null), selectedAudioGuid = ref(''), peaks = ref<number[]>([]), newLocale = ref(''), csvImport = ref<HTMLInputElement | null>(null)
const previewPresets = [{ label: 'Phone · 390 × 844', width: 390, height: 844 }, { label: 'Tablet · 1024 × 768', width: 1024, height: 768 }, { label: 'Desktop · 1920 × 1080', width: 1920, height: 1080 }, { label: 'Ultrawide · 2560 × 1080', width: 2560, height: 1080 }]
const previewPresetIndex = ref(2), previewDpi = ref(1), previewSafeArea = ref(true), previewRtl = ref(false)
const uiAudioSlots = ['hover', 'press', 'focus', 'cancel'] as const
const defaultBuses = ['Master', 'Music', 'SFX', 'UI']
const audioSettings = physicsState.audioSettings, audioDiagnostics = reactive(audioRuntime.diagnostics)
const selectedUi = computed(() => physicsState.world.entities.find(entity => entity.id === physicsState.focusEntityID && entity.hasComponent('RectTransform')) ?? null)
const selectedCanvas = computed(() => selectedUi.value?.getComponent<Canvas>('Canvas') ?? physicsState.world.entities.map(entity => entity.getComponent<Canvas>('Canvas')).find(Boolean) ?? null)
const previewPreset = computed(() => previewPresets[previewPresetIndex.value] ?? previewPresets[2])
const devicePreviewStyle = computed(() => ({ aspectRatio: `${previewPreset.value.width}/${previewPreset.value.height}`, width: `${Math.min(100, previewPreset.value.width / previewPreset.value.height * 55)}%` }))
const uiEntities = computed(() => physicsState.world.entities.filter(entity => entity.hasComponent('RectTransform')))
const focusableCount = computed(() => uiEntities.value.filter(entity => entity.getComponent<RectTransform>('RectTransform')?.focusable).length)
const labeledControlCount = computed(() => uiEntities.value.filter(entity => { const rect = entity.getComponent<RectTransform>('RectTransform'); return rect?.focusable && Boolean(rect.accessibilityLabel || entity.getComponent<Text>('Text')?.text || entity.getComponent<Checkbox>('Checkbox')?.label) }).length)
const remapWidgetCount = computed(() => uiEntities.value.filter(entity => Boolean(entity.getComponent<RectTransform>('RectTransform')?.remapAction)).length)
const layoutCounts = computed(() => uiEntities.value.filter(entity => entity.getComponent<Panel>('Panel')?.layout !== 'None').length)
const uiPrefabCount = computed(() => assetState.records.filter(asset => asset.assetType === 'prefab' && asset.path.includes('/UI')).length)
const themeAssets = computed(() => assetState.records.filter(asset => asset.assetType === 'uiTheme'))
const localeAssets = computed(() => assetState.records.filter(asset => asset.assetType === 'localization'))
const knownLocales = computed(() => [...new Set([localizationSettings.sourceLocale, localizationSettings.previewLocale, ...localizationSettings.fallbackChain, ...localizationSettings.buildLocales, ...localeAssets.value.map(asset => asset.settings.localizationSettings.locale)])].filter(Boolean).sort())
const audioAssets = computed(() => assetState.records.filter(asset => asset.assetType === 'audio'))
const extractedKeys = computed(() => extractLocalizationKeys(physicsState.world.entities, assetState.records.filter(asset => asset.assetType === 'script').map(asset => ({ path: asset.path, source: readTextAsset(asset.uuid) ?? '' }))))
const loadedLocaleTables = computed(() => localeAssets.value.flatMap(asset => { const table = readLocalizationTable(asset.uuid); return table ? [table] : [] }))
const missingEntries = computed(() => missingLocalizationReport(extractedKeys.value, loadedLocaleTables.value))
const accessibilityIssues = computed(() => auditUiAccessibility(physicsState.world.entities, runtimeAccessibilitySettings.minimumTargetSize))
const selectedAudio = computed(() => audioAssets.value.find(asset => asset.uuid === selectedAudioGuid.value) ?? null)
const waveformPoints = computed(() => peaks.value.length ? peaks.value.map((peak, index) => `${index},${50 - peak * 46}`).join(' ') : '0,50 512,50')
const themeAccent = computed({ get: () => String(themeDraft.value?.variables.accent ?? '#4f96ff'), set: value => { if (themeDraft.value) themeDraft.value.variables.accent = value } })
const themeSurface = computed({ get: () => String(themeDraft.value?.variables.surface ?? '#232934'), set: value => { if (themeDraft.value) themeDraft.value.variables.surface = value } })
const themeRadius = computed({ get: () => Number(themeDraft.value?.variables.radius ?? 10), set: value => { if (themeDraft.value) themeDraft.value.variables.radius = value } })
const themeSpacing = computed({ get: () => Number(themeDraft.value?.variables.spacing ?? 8), set: value => { if (themeDraft.value) themeDraft.value.variables.spacing = value } })
const themeFontSize = computed({ get: () => Number(themeDraft.value?.variables.fontSize ?? 16), set: value => { if (themeDraft.value) themeDraft.value.variables.fontSize = value } })
let diagnosticTimer = window.setInterval(() => Object.assign(audioDiagnostics, audioRuntime.diagnostics), 160)

watch(selectedThemeReference, reference => { themeDraft.value = reference ? readUiTheme(reference) : null }, { immediate: true })
watch(selectedLocaleReference, reference => { localeDraft.value = reference ? readLocalizationTable(reference) : null }, { immediate: true })
watch(selectedAudioGuid, () => { void analyzeWaveform() })
onBeforeUnmount(() => { window.clearInterval(diagnosticTimer) })

function createCanvas() { createUiEntity('Canvas'); pushHistory('Create UI Canvas') }
function applyPreviewToCanvas() { const canvas = selectedCanvas.value; if (!canvas) return; canvas.referenceSize = { x: previewPreset.value.width, y: previewPreset.value.height }; canvas.dpiScale = previewDpi.value; canvas.safeArea = previewSafeArea.value; canvas.localePreview = previewRtl.value ? 'ar' : localizationSettings.previewLocale; pushHistory('Apply responsive canvas preview', 'project:ui') }
function saveUiScene() { if (!selectedUi.value) return; const reference = createPrefabFromEntities([selectedUi.value.id], `${selectedUi.value.name} UI`); const asset = resolveAsset(reference); if (asset) moveAsset(asset.uuid, 'Assets/Prefabs/UI') }
function newTheme() { selectedThemeReference.value = createUiTheme(t('newThemeName')); pushHistory('Create UI theme') }
function saveTheme() { if (themeDraft.value && selectedThemeReference.value && writeUiTheme(selectedThemeReference.value, themeDraft.value)) pushHistory('Edit UI theme', `asset:${selectedThemeReference.value}`) }
function createLocale() { const locale = newLocale.value.trim(); if (!locale) return; selectedLocaleReference.value = createLocalizationTable(locale); newLocale.value = ''; pushHistory('Create localization table') }
function commitPresentation() { pushHistory('Edit presentation settings', 'project:presentation') }
function setFallbacks(event: Event) { localizationSettings.fallbackChain = (event.target as HTMLInputElement).value.split(',').map(value => value.trim()).filter(Boolean).slice(0, 16); commitPresentation() }
function toggleBuildLocale(locale: string, event: Event) { const checked = (event.target as HTMLInputElement).checked; localizationSettings.buildLocales = checked ? [...new Set([...localizationSettings.buildLocales, locale])] : localizationSettings.buildLocales.filter(value => value !== locale); if (!localizationSettings.buildLocales.includes(localizationSettings.sourceLocale)) localizationSettings.buildLocales.push(localizationSettings.sourceLocale); commitPresentation() }
function addLocaleEntry() { if (!localeDraft.value || Object.keys(localeDraft.value.entries).length >= 20_000) return; let index = Object.keys(localeDraft.value.entries).length + 1, key = `new.key.${index}`; while (localeDraft.value.entries[key] !== undefined) key = `new.key.${++index}`; localeDraft.value.entries[key] = '' }
async function removeLocaleEntry(key: string) { if (!localeDraft.value) return; const approved = await requestConfirmation({ title: t('removeEntry'), message: key, confirmLabel: t('removeEntry'), cancelLabel: t('cancel'), destructive: true }); if (approved) delete localeDraft.value.entries[key] }
function displayLocaleValue(value: LocalizationValue): string { return typeof value === 'string' ? value : JSON.stringify(value) }
function setLocaleValue(key: string, event: Event) { if (!localeDraft.value) return; const value = (event.target as HTMLTextAreaElement).value; try { const parsed = JSON.parse(value) as unknown; localeDraft.value.entries[key] = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as Record<string, string> : value } catch { localeDraft.value.entries[key] = value } }
function saveLocale() { if (localeDraft.value && selectedLocaleReference.value && writeLocalizationTable(selectedLocaleReference.value, localeDraft.value)) { pushHistory('Edit localization table', `asset:${selectedLocaleReference.value}`); assetState.generation++ } }
function setFontFallbacks(event: Event) { if (localeDraft.value) localeDraft.value.fontFallbacks = (event.target as HTMLInputElement).value.split(',').map(value => value.trim()).filter(Boolean).slice(0, 16) }
function exportCsv() { if (!localeDraft.value) return; const blob = new Blob([exportLocalizationCsv(localeDraft.value)], { type: 'text/csv;charset=utf-8' }), anchor = document.createElement('a'); anchor.href = URL.createObjectURL(blob); anchor.download = `${localeDraft.value.locale}.csv`; anchor.click(); URL.revokeObjectURL(anchor.href) }
async function importCsv(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file || !localeDraft.value) return; try { localeDraft.value = importLocalizationCsv(await file.text(), localeDraft.value.locale, localeDraft.value); pushHistory('Import localization CSV', `asset:${selectedLocaleReference.value}`) } finally { (event.target as HTMLInputElement).value = '' } }
function addBus() { const index = audioSettings.mixer.buses.length + 1; audioSettings.mixer.buses.push({ id: `Bus-${index}`, name: `Bus ${index}`, gain: 1, mute: false, solo: false, parent: 'Master', voiceLimit: 32, sends: [], effects: [] }); commitAudio() }
async function removeBus(id: string) { const approved = await requestConfirmation({ title: t('removeAudioBus'), message: id, confirmLabel: t('removeAudioBus'), cancelLabel: t('cancel'), destructive: true }); if (!approved) return; audioSettings.mixer.buses = audioSettings.mixer.buses.filter(bus => bus.id !== id); for (const bus of audioSettings.mixer.buses) { if (bus.parent === id) bus.parent = 'Master'; bus.sends = bus.sends.filter(send => send.target !== id) } commitAudio() }
function addEffect(bus: AudioMixerBusSettings) { if (bus.effects.length >= 8) return; bus.effects.push({ id: `effect-${Date.now().toString(36)}`, kind: 'LowPass', enabled: true, wet: 1, frequency: 1200, q: .7, threshold: -24, ratio: 4, time: .18, feedback: .25 }); commitAudio() }
function addSend(bus: AudioMixerBusSettings) { const target = audioSettings.mixer.buses.find(candidate => candidate.id !== bus.id); if (target && bus.sends.length < 16) { bus.sends.push({ target: target.id, gain: .25, enabled: true }); commitAudio() } }
function captureSnapshot() { const index = audioSettings.mixer.snapshots.length + 1; audioSettings.mixer.snapshots.push({ id: `snapshot-${Date.now().toString(36)}`, name: `${t('snapshot')} ${index}`, masterVolume: audioSettings.masterVolume, busGains: Object.fromEntries(audioSettings.mixer.buses.map(bus => [bus.id, bus.gain])) }); commitAudio() }
function addDucking() { if (audioSettings.mixer.ducking.length >= 32 || audioSettings.mixer.buses.length < 2) return; audioSettings.mixer.ducking.push({ id: `duck-${Date.now().toString(36)}`, triggerBus: audioSettings.mixer.buses.find(bus => bus.id === 'SFX')?.id ?? audioSettings.mixer.buses[0].id, targetBus: audioSettings.mixer.buses.find(bus => bus.id === 'Music')?.id ?? audioSettings.mixer.buses[1].id, reductionDb: -12, attack: .04, release: .35, enabled: true }); commitAudio() }
function commitAudio() { Object.assign(audioSettings, normalizeAudioSettings(audioSettings)); pushHistory('Edit audio mixer', 'project:audio') }
function commitAssetAudio() { const asset = selectedAudio.value; if (!asset) return; const settings = asset.settings.audioSettings; settings.loopStart = Math.min(asset.duration, Math.max(0, Number(settings.loopStart) || 0)); settings.loopEnd = Math.min(asset.duration, Math.max(0, Number(settings.loopEnd) || 0)); if (settings.loopEnd > 0 && settings.loopEnd < settings.loopStart) settings.loopEnd = settings.loopStart; assetState.generation++; pushHistory('Edit audio import settings', `asset:${asset.uuid}`) }
function loopMarker(time: number): number { const duration = Math.max(.0001, selectedAudio.value?.duration ?? 0); return Math.min(512, Math.max(0, time / duration * 512)) }
async function analyzeWaveform() { const asset = selectedAudio.value; peaks.value = []; if (!asset?.source || typeof AudioContext === 'undefined') return; let context: AudioContext | null = null; try { context = new AudioContext(); const response = await fetch(asset.source), buffer = await context.decodeAudioData(await response.arrayBuffer()), source = buffer.getChannelData(0), bucket = Math.max(1, Math.floor(source.length / 512)), values: number[] = []; let absolutePeak = 0; for (let offset = 0; offset < source.length; offset += bucket) { let peak = 0; for (let index = offset; index < Math.min(source.length, offset + bucket); index++) peak = Math.max(peak, Math.abs(source[index])); values.push(peak); absolutePeak = Math.max(absolutePeak, peak) } peaks.value = values.slice(0, 512); asset.settings.audioSettings.normalizationGain = absolutePeak > 1e-9 ? Math.min(16, Math.pow(10, asset.settings.audioSettings.targetPeakDb / 20) / absolutePeak) : 1; asset.duration = buffer.duration } catch { peaks.value = [] } finally { void context?.close() } }
</script>

